await bot.equipItem(/bronze sword/i);
await bot.equipItem(/wooden shield/i);
await sdk.sendSetCombatStyle(1); // try strength/attack - will check style names
const s = sdk.getState();
const styles = s.combatStyle?.styles.map(x => `${x.index}: ${x.name} (${x.trainsSkills.join('/')})`);
return { styles: styles, player: { x: s.player.x, z: s.player.z }, hp: s.player.hp };

// Kill loop helper: attack target by pattern, wait for its death (index disappears), eat if HP low
async function killOne(pattern, timeoutMs = 60000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const s = sdk.getState();
    // Eat food if HP low
    if (s.player.hp <= 5) {
      const food = sdk.findInventoryItem(/bread|shrimp/i);
      if (food) { await bot.eatFood(food); continue; }
    }
    const npc = sdk.findNearbyNpc(pattern, { reachable: true });
    if (!npc) return { done: true, reason: 'npc_not_found' };
    const idx = npc.index;
    // If we're in combat already (with this npc or another), wait
    if (s.player.combat.inCombat) {
      // check target still exists
      const still = s.nearbyNpcs.find(n => n.index === idx);
      if (still) { await new Promise(r => setTimeout(r, 600)); continue; }
      return { done: true, reason: 'killed' };
    }
    const res = await bot.attack(npc);
    if (!res.success) { await new Promise(r => setTimeout(r, 500)); continue; }
    // wait for it to die: poll until index disappears or timeout
    const sub = Date.now();
    while (Date.now() - sub < 20000) {
      await new Promise(r => setTimeout(r, 500));
      const cur = sdk.getState();
      if (cur.player.hp <= 5) break; // go eat / re-evaluate
      const alive = cur.nearbyNpcs.some(n => n.index === idx);
      if (!alive) return { done: true, reason: 'npc_gone' };
    }
  }
  return { done: false, reason: 'timeout' };
}
const man = await killOne(/^man$/i, 50000);
return { man };

